-- SIMANTAP full schema - MariaDB 10.4+/MySQL 8.x
CREATE DATABASE IF NOT EXISTS db_simantab CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE db_simantab;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

CREATE TABLE IF NOT EXISTS institutions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,short_name VARCHAR(80),address TEXT,phone VARCHAR(30),email VARCHAR(180),website VARCHAR(180),logo_path VARCHAR(500),letterhead_path VARCHAR(500),stamp_path VARCHAR(500),timezone VARCHAR(60) DEFAULT 'Asia/Jakarta',is_active TINYINT(1) DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS organization_units(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,parent_id BIGINT UNSIGNED NULL,code VARCHAR(30) NOT NULL,name VARCHAR(180) NOT NULL,short_name VARCHAR(60),unit_type VARCHAR(80),level_no SMALLINT UNSIGNED DEFAULT 1,address TEXT,email VARCHAR(180),phone VARCHAR(30),letterhead_path VARCHAR(500),logo_path VARCHAR(500),stamp_path VARCHAR(500),sort_order INT DEFAULT 0,is_active TINYINT(1) DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME NULL,UNIQUE KEY uq_unit(institution_id,code),KEY idx_unit_parent(parent_id),FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(parent_id) REFERENCES organization_units(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS positions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,code VARCHAR(30) NOT NULL,name VARCHAR(180) NOT NULL,level_no SMALLINT UNSIGNED,is_structural TINYINT(1) DEFAULT 0,is_active TINYINT(1) DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME NULL,UNIQUE KEY uq_position(institution_id,code),FOREIGN KEY(institution_id) REFERENCES institutions(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS employees(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,employee_no VARCHAR(60) NOT NULL,national_id VARCHAR(40),full_name VARCHAR(180) NOT NULL,front_title VARCHAR(60),back_title VARCHAR(80),gender ENUM('M','F','U') DEFAULT 'U',birth_place VARCHAR(100),birth_date DATE,email VARCHAR(180),phone VARCHAR(30),photo_path VARCHAR(500),employment_status VARCHAR(60),is_active TINYINT(1) DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME NULL,UNIQUE KEY uq_employee(institution_id,employee_no),KEY idx_employee_name(full_name),FOREIGN KEY(institution_id) REFERENCES institutions(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,employee_id BIGINT UNSIGNED NULL,username VARCHAR(80) NOT NULL,email VARCHAR(180),password_hash VARCHAR(255) NOT NULL,status ENUM('active','inactive','locked') DEFAULT 'active',must_change_password TINYINT(1) DEFAULT 0,failed_login_count SMALLINT UNSIGNED DEFAULT 0,locked_until DATETIME,last_login_at DATETIME,last_login_ip VARCHAR(45),locale VARCHAR(10) DEFAULT 'id',notification_preferences JSON,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME NULL,UNIQUE KEY uq_username(institution_id,username),UNIQUE KEY uq_user_email(institution_id,email),UNIQUE KEY uq_user_employee(employee_id),FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS roles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NULL,code VARCHAR(60) NOT NULL,name VARCHAR(120) NOT NULL,description TEXT,is_system TINYINT(1) DEFAULT 0,is_active TINYINT(1) DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_role(institution_id,code),FOREIGN KEY(institution_id) REFERENCES institutions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS permissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(100) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL,module VARCHAR(80) NOT NULL,description TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS role_permissions(role_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS document_types(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NULL,code VARCHAR(30) NOT NULL,name VARCHAR(120) NOT NULL,description TEXT,requires_assignment TINYINT(1) DEFAULT 0,requires_report TINYINT(1) DEFAULT 0,requires_legal_review TINYINT(1) DEFAULT 0,is_active TINYINT(1) DEFAULT 1,sort_order INT DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_doc_type(institution_id,code),FOREIGN KEY(institution_id) REFERENCES institutions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_roles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,role_id BIGINT UNSIGNED NOT NULL,institution_id BIGINT UNSIGNED NOT NULL,unit_id BIGINT UNSIGNED NULL,document_type_id BIGINT UNSIGNED NULL,confidentiality_scope ENUM('normal','important','urgent','secret','all') DEFAULT 'normal',valid_from DATE,valid_until DATE,created_by BIGINT UNSIGNED NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_user_role(user_id,role_id,institution_id,unit_id,document_type_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(unit_id) REFERENCES organization_units(id) ON DELETE CASCADE,FOREIGN KEY(document_type_id) REFERENCES document_types(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS employee_unit_histories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,employee_id BIGINT UNSIGNED NOT NULL,unit_id BIGINT UNSIGNED NOT NULL,position_id BIGINT UNSIGNED NULL,started_on DATE NOT NULL,ended_on DATE,is_primary TINYINT(1) DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_emp_history(employee_id,started_on,ended_on),FOREIGN KEY(employee_id) REFERENCES employees(id),FOREIGN KEY(unit_id) REFERENCES organization_units(id),FOREIGN KEY(position_id) REFERENCES positions(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS official_assignments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,employee_id BIGINT UNSIGNED NOT NULL,unit_id BIGINT UNSIGNED NOT NULL,position_id BIGINT UNSIGNED NOT NULL,decree_number VARCHAR(120),started_on DATE NOT NULL,ended_on DATE,is_acting TINYINT(1) DEFAULT 0,is_active TINYINT(1) DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_official(unit_id,position_id,is_active),FOREIGN KEY(employee_id) REFERENCES employees(id),FOREIGN KEY(unit_id) REFERENCES organization_units(id),FOREIGN KEY(position_id) REFERENCES positions(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS delegations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,delegator_user_id BIGINT UNSIGNED NOT NULL,delegate_user_id BIGINT UNSIGNED NOT NULL,institution_id BIGINT UNSIGNED NOT NULL,unit_id BIGINT UNSIGNED NULL,role_id BIGINT UNSIGNED NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,reason TEXT NOT NULL,status ENUM('scheduled','active','expired','cancelled') DEFAULT 'scheduled',created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_delegation(delegator_user_id,starts_at,ends_at,status),FOREIGN KEY(delegator_user_id) REFERENCES users(id),FOREIGN KEY(delegate_user_id) REFERENCES users(id),FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(unit_id) REFERENCES organization_units(id),FOREIGN KEY(role_id) REFERENCES roles(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_sessions(id CHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,ip_address VARCHAR(45),user_agent VARCHAR(500),device_name VARCHAR(120),payload MEDIUMTEXT,last_activity_at DATETIME NOT NULL,expires_at DATETIME NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_session_expiry(expires_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS login_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(180) NOT NULL,user_id BIGINT UNSIGNED NULL,ip_address VARCHAR(45) NOT NULL,user_agent VARCHAR(500),was_successful TINYINT(1) DEFAULT 0,failure_reason VARCHAR(100),attempted_at DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_login_throttle(username,ip_address,attempted_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS password_reset_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_reset_expiry(expires_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS archive_classifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,parent_id BIGINT UNSIGNED NULL,code VARCHAR(50) NOT NULL,name VARCHAR(180) NOT NULL,description TEXT,retention_active_years SMALLINT UNSIGNED,retention_inactive_years SMALLINT UNSIGNED,final_action ENUM('permanent','review','destroy') DEFAULT 'review',is_active TINYINT(1) DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_archive(institution_id,code),FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(parent_id) REFERENCES archive_classifications(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS document_templates(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,unit_id BIGINT UNSIGNED NULL,document_type_id BIGINT UNSIGNED NOT NULL,code VARCHAR(50) NOT NULL,name VARCHAR(180) NOT NULL,description TEXT,is_default TINYINT(1) DEFAULT 0,is_active TINYINT(1) DEFAULT 1,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME NULL,UNIQUE KEY uq_template(institution_id,code),FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(unit_id) REFERENCES organization_units(id),FOREIGN KEY(document_type_id) REFERENCES document_types(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS document_template_versions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,template_id BIGINT UNSIGNED NOT NULL,version_no INT UNSIGNED NOT NULL,layout_json JSON NOT NULL,html_content LONGTEXT,css_content LONGTEXT,paper_size VARCHAR(20) DEFAULT 'A4',margins_json JSON,change_notes TEXT,is_published TINYINT(1) DEFAULT 0,published_at DATETIME,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_template_version(template_id,version_no),FOREIGN KEY(template_id) REFERENCES document_templates(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS numbering_schemes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,unit_id BIGINT UNSIGNED NULL,document_type_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,format_pattern VARCHAR(255) NOT NULL,reset_period ENUM('never','yearly','monthly') DEFAULT 'yearly',padding_length SMALLINT UNSIGNED DEFAULT 3,starts_from INT UNSIGNED DEFAULT 1,assign_stage ENUM('submission','approval','signature','distribution') DEFAULT 'signature',is_active TINYINT(1) DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_number_scheme(institution_id,unit_id,document_type_id,name),FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(unit_id) REFERENCES organization_units(id),FOREIGN KEY(document_type_id) REFERENCES document_types(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS numbering_sequences(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,scheme_id BIGINT UNSIGNED NOT NULL,period_key VARCHAR(20) NOT NULL,last_number BIGINT UNSIGNED DEFAULT 0,lock_version INT UNSIGNED DEFAULT 0,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_sequence(scheme_id,period_key),FOREIGN KEY(scheme_id) REFERENCES numbering_schemes(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS workflow_definitions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,unit_id BIGINT UNSIGNED NULL,document_type_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,description TEXT,conditions_json JSON,version_no INT UNSIGNED DEFAULT 1,is_active TINYINT(1) DEFAULT 1,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_workflow_match(institution_id,unit_id,document_type_id,is_active),FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(unit_id) REFERENCES organization_units(id),FOREIGN KEY(document_type_id) REFERENCES document_types(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS workflow_definition_steps(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workflow_definition_id BIGINT UNSIGNED NOT NULL,step_no SMALLINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,action_type ENUM('verification','approval','legal_review','signature','numbering','distribution') NOT NULL,execution_mode ENUM('serial','parallel') DEFAULT 'serial',approver_type ENUM('user','role','position','unit_head','document_signer') NOT NULL,approver_reference_id BIGINT UNSIGNED,minimum_approvals SMALLINT UNSIGNED DEFAULT 1,sla_minutes INT UNSIGNED,can_delegate TINYINT(1) DEFAULT 1,require_notes_on_approve TINYINT(1) DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_definition_step(workflow_definition_id,step_no),FOREIGN KEY(workflow_definition_id) REFERENCES workflow_definitions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS documents(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,owner_unit_id BIGINT UNSIGNED NOT NULL,creator_id BIGINT UNSIGNED NOT NULL,document_type_id BIGINT UNSIGNED NOT NULL,template_version_id BIGINT UNSIGNED NULL,numbering_scheme_id BIGINT UNSIGNED NULL,archive_classification_id BIGINT UNSIGNED NULL,number VARCHAR(160),agenda_number VARCHAR(80),title VARCHAR(500) NOT NULL,summary TEXT,confidentiality ENUM('normal','important','urgent','secret') DEFAULT 'normal',priority ENUM('normal','important','urgent') DEFAULT 'normal',status VARCHAR(50) DEFAULT 'draft',document_date DATE,effective_from DATE,effective_until DATE,report_due_at DATETIME,report_type ENUM('none','individual','team') DEFAULT 'none',signer_employee_id BIGINT UNSIGNED NULL,current_version_no INT UNSIGNED DEFAULT 1,verification_code VARCHAR(80),final_hash CHAR(64),submitted_at DATETIME,approved_at DATETIME,signed_at DATETIME,distributed_at DATETIME,archived_at DATETIME,cancelled_at DATETIME,cancellation_reason TEXT,revoked_at DATETIME,revocation_reason TEXT,replaced_by_document_id BIGINT UNSIGNED NULL,source_type ENUM('native','migration') DEFAULT 'native',source_reference VARCHAR(255),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME NULL,UNIQUE KEY uq_document_number(institution_id,number),UNIQUE KEY uq_verification_code(verification_code),KEY idx_document_search(institution_id,owner_unit_id,document_type_id,status,document_date),KEY idx_document_title(title(191)),FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(owner_unit_id) REFERENCES organization_units(id),FOREIGN KEY(creator_id) REFERENCES users(id),FOREIGN KEY(document_type_id) REFERENCES document_types(id),FOREIGN KEY(template_version_id) REFERENCES document_template_versions(id),FOREIGN KEY(numbering_scheme_id) REFERENCES numbering_schemes(id),FOREIGN KEY(archive_classification_id) REFERENCES archive_classifications(id),FOREIGN KEY(signer_employee_id) REFERENCES employees(id),FOREIGN KEY(replaced_by_document_id) REFERENCES documents(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS document_versions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NOT NULL,version_no INT UNSIGNED NOT NULL,content_json JSON NOT NULL,rendered_html LONGTEXT,change_summary TEXT,validation_errors JSON,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_document_version(document_id,version_no),FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS document_relations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,source_document_id BIGINT UNSIGNED NOT NULL,target_document_id BIGINT UNSIGNED NOT NULL,relation_type ENUM('replaces','revokes','references','follows_up','attachment_of') NOT NULL,notes TEXT,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_doc_relation(source_document_id,target_document_id,relation_type),FOREIGN KEY(source_document_id) REFERENCES documents(id),FOREIGN KEY(target_document_id) REFERENCES documents(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS document_parties(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NOT NULL,party_role ENUM('sender','recipient','cc','external_recipient','responsible_person') NOT NULL,party_type ENUM('user','employee','unit','position','external') NOT NULL,party_reference_id BIGINT UNSIGNED,external_name VARCHAR(180),external_organization VARCHAR(180),external_email VARCHAR(180),snapshot_json JSON,requires_follow_up TINYINT(1) DEFAULT 0,sort_order INT DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_party(document_id,party_role),KEY idx_party_ref(party_type,party_reference_id),FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS document_assignees(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NOT NULL,employee_id BIGINT UNSIGNED NOT NULL,assignment_role VARCHAR(120),is_team_leader TINYINT(1) DEFAULT 0,status ENUM('assigned','acknowledged','in_progress','completed','cancelled') DEFAULT 'assigned',acknowledged_at DATETIME,completed_at DATETIME,notes TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_assignee(document_id,employee_id),KEY idx_assignee(employee_id,status),FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE CASCADE,FOREIGN KEY(employee_id) REFERENCES employees(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS decision_clauses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NOT NULL,clause_type ENUM('considering','remembering','observing','deciding','stipulating','dictum') NOT NULL,sequence_no SMALLINT UNSIGNED NOT NULL,label VARCHAR(80),content LONGTEXT NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_clause(document_id,clause_type,sequence_no),FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS decision_team_members(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NOT NULL,employee_id BIGINT UNSIGNED NULL,external_name VARCHAR(180),identity_number VARCHAR(80),origin_position VARCHAR(180),decision_role VARCHAR(180) NOT NULL,sequence_no SMALLINT UNSIGNED DEFAULT 1,snapshot_json JSON,FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE CASCADE,FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS workflow_instances(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NOT NULL,workflow_definition_id BIGINT UNSIGNED NOT NULL,definition_snapshot JSON NOT NULL,status ENUM('pending','running','approved','rejected','cancelled') DEFAULT 'pending',current_step_no SMALLINT UNSIGNED,started_at DATETIME,completed_at DATETIME,cancelled_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_doc_workflow(document_id),FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE CASCADE,FOREIGN KEY(workflow_definition_id) REFERENCES workflow_definitions(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS workflow_steps(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workflow_instance_id BIGINT UNSIGNED NOT NULL,definition_step_id BIGINT UNSIGNED NULL,step_no SMALLINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,action_type ENUM('verification','approval','legal_review','signature','numbering','distribution') NOT NULL,execution_mode ENUM('serial','parallel') DEFAULT 'serial',minimum_approvals SMALLINT UNSIGNED DEFAULT 1,status ENUM('waiting','active','approved','revision','rejected','skipped','cancelled') DEFAULT 'waiting',sla_due_at DATETIME,activated_at DATETIME,completed_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_workflow_step(workflow_instance_id,step_no),KEY idx_step_inbox(status,sla_due_at),FOREIGN KEY(workflow_instance_id) REFERENCES workflow_instances(id) ON DELETE CASCADE,FOREIGN KEY(definition_step_id) REFERENCES workflow_definition_steps(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS workflow_step_actors(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workflow_step_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,delegated_from_user_id BIGINT UNSIGNED NULL,status ENUM('pending','acted','cancelled') DEFAULT 'pending',assigned_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_step_actor(workflow_step_id,user_id),KEY idx_actor_inbox(user_id,status),FOREIGN KEY(workflow_step_id) REFERENCES workflow_steps(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(delegated_from_user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS approvals(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workflow_step_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,decision ENUM('approved','revision','rejected') NOT NULL,notes TEXT,ip_address VARCHAR(45),user_agent VARCHAR(500),device_fingerprint VARCHAR(255),version_no_reviewed INT UNSIGNED NOT NULL,decided_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_actor_decision(workflow_step_id,actor_id),FOREIGN KEY(workflow_step_id) REFERENCES workflow_steps(id),FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS signatures(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NOT NULL,signer_user_id BIGINT UNSIGNED NOT NULL,signer_employee_id BIGINT UNSIGNED NULL,signature_type ENUM('internal_image','electronic_certified','manual_scan') DEFAULT 'internal_image',provider VARCHAR(120),certificate_serial VARCHAR(255),signed_hash CHAR(64) NOT NULL,signature_metadata JSON,ip_address VARCHAR(45),signed_at DATETIME DEFAULT CURRENT_TIMESTAMP,revoked_at DATETIME,revocation_reason TEXT,UNIQUE KEY uq_signature(document_id,signer_user_id),FOREIGN KEY(document_id) REFERENCES documents(id),FOREIGN KEY(signer_user_id) REFERENCES users(id),FOREIGN KEY(signer_employee_id) REFERENCES employees(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS document_files(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NOT NULL,document_version_id BIGINT UNSIGNED NULL,uploaded_by BIGINT UNSIGNED NOT NULL,file_role ENUM('attachment','draft_pdf','final_pdf','signature','stamp','report_attachment','migration_source') NOT NULL,original_name VARCHAR(255) NOT NULL,storage_disk VARCHAR(50) DEFAULT 'private',storage_path VARCHAR(700) NOT NULL,mime_type VARCHAR(120) NOT NULL,extension VARCHAR(20),file_size BIGINT UNSIGNED NOT NULL,checksum_sha256 CHAR(64) NOT NULL,is_encrypted TINYINT(1) DEFAULT 0,encryption_metadata JSON,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,deleted_at DATETIME NULL,KEY idx_file_document(document_id,file_role),UNIQUE KEY uq_file(document_id,checksum_sha256,file_role),FOREIGN KEY(document_id) REFERENCES documents(id),FOREIGN KEY(document_version_id) REFERENCES document_versions(id),FOREIGN KEY(uploaded_by) REFERENCES users(id)) ENGINE=InnoDB;
ALTER TABLE documents ADD COLUMN IF NOT EXISTS final_file_id BIGINT UNSIGNED NULL;
CREATE TABLE IF NOT EXISTS distributions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NOT NULL,distributed_by BIGINT UNSIGNED NOT NULL,channel ENUM('in_app','email','manual','api') DEFAULT 'in_app',notes TEXT,distributed_at DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_distribution(document_id,distributed_at),FOREIGN KEY(document_id) REFERENCES documents(id),FOREIGN KEY(distributed_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS distribution_recipients(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,distribution_id BIGINT UNSIGNED NOT NULL,recipient_type ENUM('user','employee','unit','position','external') NOT NULL,recipient_reference_id BIGINT UNSIGNED,external_name VARCHAR(180),external_email VARCHAR(180),recipient_role ENUM('recipient','cc','follow_up') DEFAULT 'recipient',delivery_status ENUM('queued','sent','delivered','failed') DEFAULT 'queued',sent_at DATETIME,delivered_at DATETIME,first_opened_at DATETIME,last_opened_at DATETIME,download_count INT UNSIGNED DEFAULT 0,failure_reason TEXT,KEY idx_recipient(recipient_type,recipient_reference_id,delivery_status),FOREIGN KEY(distribution_id) REFERENCES distributions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS distribution_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,distribution_recipient_id BIGINT UNSIGNED NOT NULL,event_type ENUM('sent','delivered','opened','downloaded','failed') NOT NULL,ip_address VARCHAR(45),user_agent VARCHAR(500),metadata JSON,occurred_at DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_dist_event(distribution_recipient_id,occurred_at),FOREIGN KEY(distribution_recipient_id) REFERENCES distribution_recipients(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dispositions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NOT NULL,parent_id BIGINT UNSIGNED NULL,created_by BIGINT UNSIGNED NOT NULL,assignee_type ENUM('user','employee','unit','position') NOT NULL,assignee_reference_id BIGINT UNSIGNED NOT NULL,instruction TEXT NOT NULL,priority ENUM('normal','important','urgent') DEFAULT 'normal',due_at DATETIME,status ENUM('new','read','in_progress','completed','returned','cancelled','overdue') DEFAULT 'new',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,completed_at DATETIME,KEY idx_disposition(assignee_type,assignee_reference_id,status,due_at),FOREIGN KEY(document_id) REFERENCES documents(id),FOREIGN KEY(parent_id) REFERENCES dispositions(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS disposition_updates(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,disposition_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,status VARCHAR(30) NOT NULL,notes TEXT,progress_percent TINYINT UNSIGNED,attachment_file_id BIGINT UNSIGNED NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_disp_update(disposition_id,created_at),FOREIGN KEY(disposition_id) REFERENCES dispositions(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(attachment_file_id) REFERENCES document_files(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS agendas(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NULL,document_assignee_id BIGINT UNSIGNED NULL,owner_user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(255) NOT NULL,description TEXT,starts_at DATETIME NOT NULL,ends_at DATETIME,timezone VARCHAR(60) DEFAULT 'Asia/Jakarta',location_type ENUM('physical','online','hybrid') DEFAULT 'physical',location VARCHAR(255),meeting_url VARCHAR(700),status ENUM('scheduled','changed','completed','cancelled') DEFAULT 'scheduled',source ENUM('document','manual','integration') DEFAULT 'document',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_agenda(owner_user_id,starts_at,status),FOREIGN KEY(document_id) REFERENCES documents(id),FOREIGN KEY(document_assignee_id) REFERENCES document_assignees(id),FOREIGN KEY(owner_user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS execution_reports(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NOT NULL,document_assignee_id BIGINT UNSIGNED NULL,report_type ENUM('individual','team') NOT NULL,author_user_id BIGINT UNSIGNED NOT NULL,team_leader_user_id BIGINT UNSIGNED NULL,status ENUM('draft','submitted','under_review','revision','approved','rejected','late') DEFAULT 'draft',actual_started_at DATETIME,actual_ended_at DATETIME,actual_location VARCHAR(255),summary LONGTEXT,results LONGTEXT,constraints_text LONGTEXT,conclusion LONGTEXT,recommendations LONGTEXT,content_json JSON,due_at DATETIME,submitted_at DATETIME,reviewed_by BIGINT UNSIGNED NULL,reviewed_at DATETIME,review_notes TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_report(document_id,status,due_at),FOREIGN KEY(document_id) REFERENCES documents(id),FOREIGN KEY(document_assignee_id) REFERENCES document_assignees(id),FOREIGN KEY(author_user_id) REFERENCES users(id),FOREIGN KEY(team_leader_user_id) REFERENCES users(id),FOREIGN KEY(reviewed_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS report_contributors(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,execution_report_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,contribution_text LONGTEXT,status ENUM('invited','draft','submitted','accepted') DEFAULT 'invited',submitted_at DATETIME,UNIQUE KEY uq_contributor(execution_report_id,user_id),FOREIGN KEY(execution_report_id) REFERENCES execution_reports(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS report_files(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,execution_report_id BIGINT UNSIGNED NOT NULL,uploaded_by BIGINT UNSIGNED NOT NULL,file_type ENUM('attachment','photo','supporting_document') NOT NULL,original_name VARCHAR(255) NOT NULL,storage_path VARCHAR(700) NOT NULL,mime_type VARCHAR(120) NOT NULL,file_size BIGINT UNSIGNED NOT NULL,checksum_sha256 CHAR(64) NOT NULL,caption VARCHAR(500),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(execution_report_id) REFERENCES execution_reports(id) ON DELETE CASCADE,FOREIGN KEY(uploaded_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reminders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,agenda_id BIGINT UNSIGNED NULL,document_id BIGINT UNSIGNED NULL,execution_report_id BIGINT UNSIGNED NULL,user_id BIGINT UNSIGNED NOT NULL,channel ENUM('in_app','email','web_push','whatsapp') DEFAULT 'in_app',remind_at DATETIME NOT NULL,event_key VARCHAR(120) NOT NULL,status ENUM('scheduled','processing','sent','failed','cancelled') DEFAULT 'scheduled',attempts SMALLINT UNSIGNED DEFAULT 0,sent_at DATETIME,last_error TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_reminder(user_id,event_key,remind_at,channel),KEY idx_reminder_queue(status,remind_at),FOREIGN KEY(agenda_id) REFERENCES agendas(id) ON DELETE CASCADE,FOREIGN KEY(document_id) REFERENCES documents(id),FOREIGN KEY(execution_report_id) REFERENCES execution_reports(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,event_key VARCHAR(160) NOT NULL,notification_type VARCHAR(80) NOT NULL,title VARCHAR(255) NOT NULL,message TEXT NOT NULL,object_type VARCHAR(80),object_id BIGINT UNSIGNED,deep_link VARCHAR(700),priority ENUM('low','normal','high','urgent') DEFAULT 'normal',read_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME,UNIQUE KEY uq_notification(user_id,event_key),KEY idx_notification(user_id,read_at,created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notification_deliveries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,notification_id BIGINT UNSIGNED NOT NULL,channel ENUM('in_app','email','web_push','whatsapp') NOT NULL,recipient_address VARCHAR(255),status ENUM('queued','processing','sent','delivered','failed','cancelled') DEFAULT 'queued',provider_message_id VARCHAR(255),attempts SMALLINT UNSIGNED DEFAULT 0,last_error TEXT,sent_at DATETIME,delivered_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_notif_channel(notification_id,channel),KEY idx_delivery_queue(status,created_at),FOREIGN KEY(notification_id) REFERENCES notifications(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NULL,actor_user_id BIGINT UNSIGNED NULL,event VARCHAR(120) NOT NULL,severity ENUM('info','warning','critical') DEFAULT 'info',object_type VARCHAR(80),object_id BIGINT UNSIGNED,description VARCHAR(500),old_values JSON,new_values JSON,metadata JSON,ip_address VARCHAR(45),user_agent VARCHAR(500),request_id CHAR(36),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_audit_object(object_type,object_id,created_at),KEY idx_audit_actor(actor_user_id,created_at),KEY idx_audit_event(institution_id,event,created_at),FOREIGN KEY(institution_id) REFERENCES institutions(id),FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS jobs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,queue VARCHAR(80) DEFAULT 'default',payload LONGTEXT NOT NULL,attempts SMALLINT UNSIGNED DEFAULT 0,reserved_at DATETIME,available_at DATETIME NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_job_queue(queue,reserved_at,available_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS failed_jobs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,uuid CHAR(36) NOT NULL UNIQUE,queue VARCHAR(80) NOT NULL,payload LONGTEXT NOT NULL,exception LONGTEXT NOT NULL,failed_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS system_settings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NULL,unit_id BIGINT UNSIGNED NULL,setting_key VARCHAR(160) NOT NULL,setting_value LONGTEXT,value_type ENUM('string','integer','boolean','json','encrypted') DEFAULT 'string',is_public TINYINT(1) DEFAULT 0,updated_by BIGINT UNSIGNED NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_setting(institution_id,unit_id,setting_key),FOREIGN KEY(institution_id) REFERENCES institutions(id) ON DELETE CASCADE,FOREIGN KEY(unit_id) REFERENCES organization_units(id) ON DELETE CASCADE,FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;

SET FOREIGN_KEY_CHECKS=1;
